const opportunities=$input.all().map(i=>i.json);
const now=Date.now();
const active=opportunities.filter(o=>!['won','lost'].includes(o.status));
const overdue=active.filter(o=>o.next_follow_up_at && new Date(o.next_follow_up_at).getTime()<now);
const noNextStep=active.filter(o=>!o.next_follow_up_at && !o.human_required && !['nurture'].includes(o.status));
const hot=active.filter(o=>['purchase_signal','interested'].includes(o.last_intent)||Number(o.lead_score||0)>=70);
const proposals=active.filter(o=>o.status==='proposal_sent');
return [{json:{checked_at:new Date().toISOString(),total_active:active.length,overdue_count:overdue.length,no_next_step_count:noNextStep.length,hot_count:hot.length,proposal_count:proposals.length,overdue_ids:overdue.map(o=>o.id),no_next_step_ids:noNextStep.map(o=>o.id),hot_ids:hot.map(o=>o.id),priority:'high'}}];

const r=$json;
const parts=[];
if(r.hot_count) parts.push(`${r.hot_count} oportunidades con señal de compra o alto score`);
if(r.overdue_count) parts.push(`${r.overdue_count} seguimientos vencidos`);
if(r.no_next_step_count) parts.push(`${r.no_next_step_count} oportunidades activas sin próximo paso`);
if(r.proposal_count) parts.push(`${r.proposal_count} propuestas en circulación`);
const message=parts.length?`Reporte de Copiloto Comercial: ${parts.join('; ')}.`:'Reporte de Copiloto Comercial: no detecté excepciones críticas.';
return [{json:{...r,executive_message:message,notify_human:parts.length>0,event:'pipeline_monitor'}}];
